process.on("uncaughtException", error => { console.error(error.message); process.exit(1); });
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {runNewAPIVideoPluginDryRun} from '../../../web/src/lib/newapi-video-plugin-checks.ts';

const input=JSON.parse(readFileSync(process.argv[2],'utf8'));
const plugin=await import(`data:text/javascript;base64,${Buffer.from(input.source).toString('base64')}`);
const model=input.options.models[0];
const file={ref:'opaque-ref',field:'input_reference',filename:'frame.png',mimeType:'image/png',size:100};
const fields={model:[model],prompt:['sample'],duration:['8'],prompt_expansion_mode:['quality'],seed:['0'],prompt_enhance:['false']};
const decode=(fields,files)=>plugin.protocols.openai_video.decodeRequest({model,body:{kind:'multipart',fields,files}});
const intent=decode(fields,[file]);
const aliasContext={model:'client-alias',upstreamModel:model,body:{kind:'multipart',fields:{...fields,model:['client-alias']},files:[file]}};
const aliasIntent=plugin.protocols.openai_video.decodeRequest(aliasContext);
assert.equal(aliasIntent.model,'client-alias');
assert.deepEqual(plugin.protocols.openai_video.decodeRequest(aliasContext),aliasIntent);
assert.equal(aliasIntent.requestBody.seed,0);
assert.equal(aliasIntent.requestBody.prompt_enhance,false);
const ctx={requestBody:intent.requestBody,model,upstreamModel:model,files:[file],apiKey:'fixture',baseUrl:input.options.base_url};
const submit=plugin.buildSubmitRequest(ctx);
assert.equal(submit.bodyType,'multipart');
assert.equal(submit.headers['Content-Type'],undefined);
assert.deepEqual(submit.parts.find(part=>part.fileRef),{name:'input_reference',fileRef:'opaque-ref',filename:'frame.png'});
assert.equal(submit.parts.find(part=>part.name==='seed').value,'0');
assert.equal(submit.parts.find(part=>part.name==='prompt_enhance').value,'false');
assert.equal(plugin.extractUsage({...ctx,usagePurpose:'facts'}).seconds,8);
const videoFile={...file,ref:'video-ref',filename:'reference.mp4',mimeType:'video/mp4'};
const videoIntent=decode(fields,[videoFile]);
const videoSubmit=plugin.buildSubmitRequest({...ctx,requestBody:videoIntent.requestBody,files:[videoFile]});
assert.deepEqual(videoSubmit.parts.find(part=>part.fileRef),{name:'input_reference',fileRef:'video-ref',filename:'reference.mp4'});
assert.throws(()=>decode({...fields,prompt_enhance:['yes']},[file]));
assert.throws(()=>decode({...fields,duration:['8','9']},[file]));
assert.throws(()=>decode(fields,[{...file,field:'unmapped'}]));
assert.throws(()=>decode(fields,[file,{...file,ref:'other-ref'}]));
assert.throws(()=>decode({...fields,'nested.constructor.prototype.pwned':['true']},[file]));
assert.equal({}.pwned,undefined);
assert.throws(()=>plugin.buildSubmitRequest({...ctx,files:[...ctx.files,{...file,ref:'unused'}]}));
assert.ok(runNewAPIVideoPluginDryRun(plugin,input).some(check=>check.includes('文件上传')));
console.log('multipart decoding, typed form values, opaque file refs and dry-run passed');
